let cachedFonts: { name: string; data: Buffer; weight: 400 | 700; style: 'normal' }[] | null = null

function loadSatoriFonts(): { name: string; data: Buffer; weight: 400 | 700; style: 'normal' }[] {
  if (cachedFonts) return cachedFonts
  const primaryRegular = join(process.cwd(), 'assets', 'fonts', 'Inter.ttf')
  const primaryBold = join(process.cwd(), 'assets', 'fonts', 'Inter-Bold.ttf')
  const fallbackRegular = '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
  const fallbackBold = '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'

  const reg = existsSync(primaryRegular)
    ? readFileSync(primaryRegular)
    : readFileSync(fallbackRegular)
  const bold = existsSync(primaryBold)
    ? readFileSync(primaryBold)
    : existsSync(fallbackBold)
      ? readFileSync(fallbackBold)
      : reg

  cachedFonts = [
    { name: 'Inter', data: reg, weight: 400, style: 'normal' },
    { name: 'Inter', data: bold, weight: 700, style: 'normal' },
  ]
  return cachedFonts
}

/**
 * RPG-Style Base-400 ELO Ladder Tiers:
 * - 400 – 699   : 🌱 Novice (Pawn)
 * - 700 – 999   : ⚔️ Apprentice (Knight/Bishop)
 * - 1000 – 1299 : 🛡️ Tactician (Rook)
 * - 1300 – 1599 : 👑 Master (Queen)
 * - 1600+       : 🔥 Grandmaster (King)
 */
export function getEloTier(elo: number): {
  title: string
  icon: string
  badge: string
  pieceLabel: string
  color: string
} {
  if (elo >= 1600) {
    return { title: 'Grandmaster', icon: '🔥', badge: '🔥 Grandmaster', pieceLabel: 'King', color: '#ef4444' }
  }
  if (elo >= 1300) {
    return { title: 'Master', icon: '👑', badge: '👑 Master', pieceLabel: 'Queen', color: '#f59e0b' }
  }
  if (elo >= 1000) {
    return { title: 'Tactician', icon: '🛡️', badge: '🛡️ Tactician', pieceLabel: 'Rook', color: '#38bdf8' }
  }
  if (elo >= 700) {
    return { title: 'Apprentice', icon: '⚔️', badge: '⚔️ Apprentice', pieceLabel: 'Knight/Bishop', color: '#a3d160' }
  }
  return { title: 'Novice', icon: '🌱', badge: '🌱 Novice', pieceLabel: 'Pawn', color: '#a09d98' }
}

export function formatClockMs(ms: number): string {
  const clamped = Math.max(0, Math.ceil(ms / 1000))
  const minutes = Math.floor(clamped / 60)
  const seconds = clamped % 60
  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
}

export function parseTimeControlArg(input?: string): TimeControlMode | null {
  if (!input) return null
  const low = input.trim().toLowerCase()
  if (low === 'bullet' || low === 'kilat' || low === '3m') return 'bullet'
  if (low === 'blitz' || low === 'cepat' || low === '7m') return 'blitz'
  if (low === 'rapid' || low === 'lambat' || low === '15m') return 'rapid'
  if (low === 'casual' || low === 'santai' || low === 'unrated' || low === 'untimed') return 'casual'
  return null
}

function normalizeSanForBook(san: string): string {
  return san.replace(/[+#!?]/g, '').trim()
}

export function lookupOpeningBook(
  sanSequence: readonly string[],
): { eco: string; name: string; matchedMoves: number; exactPrefixMatch: boolean } | null {
  if (sanSequence.length === 0) return null
  const normalizedSeq = sanSequence.map(normalizeSanForBook)
  const seqStr = normalizedSeq.join(' ')

  let bestEntry: OpeningBookEntry | null = null
  let bestCount = 0
  let exactMatch = false

  for (const entry of FIDE_ECO_OPENING_BOOK) {
    const entryMoves = entry.moves.split(' ')
    if (entry.moves === seqStr) {
      return {
        eco: entry.eco,
        name: entry.name,
        matchedMoves: entryMoves.length,
        exactPrefixMatch: true,
      }
    }
    // Check if the played sequence is a prefix of a known book line
    if (
      normalizedSeq.length <= entryMoves.length &&
      entryMoves.slice(0, normalizedSeq.length).join(' ') === seqStr
    ) {
      exactMatch = true
      if (normalizedSeq.length > bestCount) {
        bestCount = normalizedSeq.length
        bestEntry = entry
      }
    } else if (
      normalizedSeq.length > entryMoves.length &&
      seqStr.startsWith(entry.moves + ' ')
    ) {
      if (entryMoves.length > bestCount) {
        bestCount = entryMoves.length
        bestEntry = entry
      }
    }
  }

  if (!bestEntry) return null
  return {
    eco: bestEntry.eco,
    name: bestEntry.name,
    matchedMoves: bestCount,
    exactPrefixMatch: exactMatch,
  }
}

