  async renderReviewVideoMp4(
    state: ChessGameState,
    whatsapp?: WhatsAppPort,
  ): Promise<{ mp4Buffer: Buffer; summary: GameReviewSummary }> {
    const ratedCat: RatedCategory =
      state.timeControl === 'rapid'
        ? 'rapid'
        : state.timeControl === 'bullet'
          ? 'bullet'
          : 'blitz'

    const wProfile = state.whiteJid.startsWith('bot:')
      ? null
      : this.getPlayerElo(state.whiteJid, state.whiteName, ratedCat)
    const bProfile = state.blackJid.startsWith('bot:')
      ? null
      : this.getPlayerElo(state.blackJid, state.blackName, ratedCat)

    const botElo = state.botLevel ? BOT_LEVEL_SPECS[state.botLevel].eloEstimate : BASE_INITIAL_ELO
    const whiteElo = wProfile?.elo ?? botElo
    const blackElo = bProfile?.elo ?? botElo

    // Run Stockfish 16 batch evaluation (or tactical fallback) across all game positions
    const allFens =
      state.moveHistory.length > 0
        ? [state.moveHistory[0].fenBefore, ...state.moveHistory.map((m) => m.fenAfter)]
        : []
    const batchEval = await batchEvaluateFensWithStockfish(allFens, 8)
    const summary = analyzeGameHistory(state, whiteElo, blackElo, batchEval)

    const [whiteAvatarUrl, blackAvatarUrl] = await Promise.all([
      this.getAvatarDataUrl(whatsapp, state.whiteJid),
      this.getAvatarDataUrl(whatsapp, state.blackJid),
    ])

    const frames: Buffer[] = []
    frames.push(await this.renderReviewFramePng(state, summary, null, whiteAvatarUrl, blackAvatarUrl))

    const stepsToRender =
      summary.steps.length > 60
        ? summary.steps.filter((_, idx) => idx % 2 === 0 || idx === summary.steps.length - 1)
        : summary.steps

    for (const step of stepsToRender) {
      frames.push(await this.renderReviewFramePng(state, summary, step, whiteAvatarUrl, blackAvatarUrl))
    }

    const summaryPng = await this.renderReviewSummaryFramePng(summary)
    frames.push(summaryPng, summaryPng, summaryPng)

    const outPath = join(tmpdir(), `allybot_chess_review_${Date.now()}_${randomBytes(4).toString('hex')}.mp4`)

    await new Promise<void>((resolve, reject) => {
      const child = spawn(
        'ffmpeg',
        [
          '-y',
          '-hide_banner',
          '-loglevel',
          'error',
          '-f',
          'image2pipe',
          '-framerate',
          '1',
          '-i',
          'pipe:0',
          '-c:v',
          'libx264',
          '-pix_fmt',
          'yuv420p',
          '-movflags',
          '+faststart',
          outPath,
        ],
        { shell: false, stdio: ['pipe', 'ignore', 'pipe'] },
      )

      const timer = setTimeout(() => {
        child.kill('SIGKILL')
        reject(new Error('FFmpeg review video generation timed out'))
      }, 45_000)

      child.once('error', (err) => {
        clearTimeout(timer)
        reject(err)
      })

      child.once('close', (code) => {
        clearTimeout(timer)
        if (code !== 0) reject(new Error(`FFmpeg exited with code ${code}`))
        else resolve()
      })

      for (const frame of frames) {
        child.stdin.write(frame)
      }
      child.stdin.end()
    })

    const mp4Buffer = await readFile(outPath)
    await unlink(outPath).catch(() => {})
    return { mp4Buffer, summary }
  }

